<?php require_once __DIR__.'/lib.php'; ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AB Premiere | Socios</title><link rel="stylesheet" href="assets/style.css"></head><body><header><div class="brand"><img src="assets/logo-ab-premiere.png">AB PREMIERE</div><a href="/admin">Administración →</a></header><main class="wrap"><section class="hero"><img src="assets/logo-ab-premiere.png"><h1>Control de Visitas <span style="color:var(--gold2)">Familia AB</span></h1><p>Consulta tus beneficios, selecciona tu barbero y registra tu servicio.</p></section><section class="card portal"><div class="tabs"><button class="btn active" id="tabLookup" onclick="tab('lookup')">Ingresar código</button><button class="btn alt" id="tabRegister" onclick="tab('register')">Nuevo socio</button></div>
<div id="lookup" class="panel active"><h2>Ingresa tu código de 4 dígitos</h2><form id="lookupForm"><input id="code" maxlength="4" pattern="[0-9]{4}" inputmode="numeric" placeholder="Ej. 2026" required><button class="btn wide" style="margin-top:15px">Consultar mis datos</button></form><div id="lookupMessage"></div><div id="clientArea" class="hidden"><div id="clientCard"></div><div class="grid2"><div><label>Selecciona barbero</label><select id="barber"></select></div><div><label>Selecciona corte o servicio</label><select id="service"></select></div></div><button class="btn wide" style="margin-top:18px" onclick="registerVisit()">Registrar visita</button></div></div>
<div id="register" class="panel"><h2>Registro de nuevo socio</h2><div class="camera"><video id="video" autoplay playsinline></video></div><p style="text-align:center"><button class="btn alt" onclick="startCamera()">Encender cámara</button> <button class="btn" onclick="capture()">Tomar foto</button></p><canvas id="canvas" hidden></canvas><form id="registerForm"><div class="grid2"><div><label>Nombre completo</label><input id="fullName" required></div><div><label>Fecha de nacimiento</label><input id="birthDate" type="date" required></div><div><label>Teléfono</label><input id="phone"></div><div><label>Código de autorización</label><input id="release" type="password" required></div></div><button class="btn wide" style="margin-top:18px">Crear socio</button></form><div id="registerMessage"></div></div></section></main><footer>AB PREMIERE · Reynosa, Tamaulipas</footer>
<script>const $=x=>document.getElementById(x),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current=null,photo='',stream=null;async function api(action,data=null){const r=await fetch('api.php?action='+action,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):null}),j=await r.json();if(!r.ok)throw Error(j.message);return j}function tab(id){document.querySelectorAll('.panel,.tabs .btn').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');$('tab'+id[0].toUpperCase()+id.slice(1)).classList.add('active');if(id==='register')startCamera()}function msg(id,text,error=false){$(id).innerHTML=`<div class="message ${error?'error':''}">${text}</div>`}async function loadCatalogs(){const d=await api('catalogs');$('barber').innerHTML='<option value="">Selecciona...</option>'+d.barbers.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('service').innerHTML='<option value="">Selecciona...</option>'+d.services.map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.points} puntos</option>`).join('')}$('lookupForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('lookup',{code:$('code').value});current=d.client;let benefit=current.one_away?'<div class="message">🎁 En tu siguiente corte recibirás un beneficio.</div>':'';let birthday=current.birthday_month?'<div class="message">🎂 ¡Feliz mes de cumpleaños!</div>':'';$('clientCard').innerHTML=`<div class="client-result"><img class="avatar" src="${current.photo_url||'assets/logo-ab-premiere.png'}"><div><h2>${esc(current.full_name)}</h2><p>Código: <b>${esc(current.code)}</b> · Nacimiento: ${esc(current.birth_date||'—')}<br>Registro: ${esc(current.created_at.slice(0,10))} · Última visita: ${esc(current.last_visit||'Aún no tiene visitas')}</p><div class="stats"><div class="stat"><b>${current.visits}</b>Cortes</div><div class="stat"><b>${current.points}</b>Puntos</div><div class="stat"><b>${current.next_courtesy}</b>Próxima cortesía</div></div><h3>Mis visitas por día</h3><div class="weekday-stats">${['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'].map((n,i)=>`<div><span>${n}</span><div class="percent-track"><i style="width:${current.weekday_percentages[i]}%"></i></div><b>${current.weekday_percentages[i]}%</b></div>`).join('')}</div>${benefit}${birthday}</div></div>`;$('lookupMessage').innerHTML='';$('clientArea').classList.remove('hidden')}catch(x){$('clientArea').classList.add('hidden');msg('lookupMessage',esc(x.message),true)}};async function registerVisit(){if(!current)return;try{const d=await api('visit',{code:current.code,barber_id:$('barber').value,service_id:$('service').value});if(d.courtesy_won){celebrate();msg('lookupMessage','🎉 <b>¡Felicidades! Has ganado una cortesía.</b>')}else msg('lookupMessage',esc(d.message)+` Ganaste ${d.points_earned} puntos.`);$('clientArea').classList.add('hidden');$('lookupForm').reset()}catch(x){msg('lookupMessage',esc(x.message),true)}}function celebrate(){const a=new(window.AudioContext||window.webkitAudioContext)();[523,659,784,1047].forEach((f,i)=>{const o=a.createOscillator(),g=a.createGain();o.frequency.value=f;o.connect(g);g.connect(a.destination);g.gain.setValueAtTime(.15,a.currentTime+i*.18);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+i*.18+.4);o.start(a.currentTime+i*.18);o.stop(a.currentTime+i*.18+.4)})}async function startCamera(){try{if(stream)return;stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'}});$('video').srcObject=stream}catch(x){msg('registerMessage','La cámara no está disponible; puedes continuar sin foto.',true)}}function capture(){if(!stream)return;const c=$('canvas'),v=$('video');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);photo=c.toDataURL('image/jpeg',.8);msg('registerMessage','Fotografía capturada.')}$('registerForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('register',{full_name:$('fullName').value,birth_date:$('birthDate').value,phone:$('phone').value,release_code:$('release').value,photo});msg('registerMessage',`🎉 Socio creado. Código: <b style="font-size:25px">${d.code}</b>`);e.target.reset();photo=''}catch(x){msg('registerMessage',esc(x.message),true)}};loadCatalogs();</script></body></html>
